/bin/zsh -lc "python3 - <<'PY'
from pathlib import Path
import re
paths = [Path('README.md'), Path('AGENTS.md'), Path('CLAUDE.md'), *Path('docs').rglob('*.md')]
errors = []
count = 0
for path in paths:
    for target in re.findall(r'\\]\\((["'^)]+)'"\\)', path.read_text()):
        count += 1
        if not (path.parent / target.split('#')[0]).exists():
            errors.append(f'{path}: {target}')
print(f'Checked {count} local Markdown links across {len(paths)} documents.')
if errors:
    raise SystemExit('\\n'.join(errors))
print('All links resolve.')
for directory in (Path('tasklist/__pycache__'), Path('tests/__pycache__')):
    if directory.exists():
        print(f'Generated cache: {directory}: {[p.name for p in directory.iterdir()]}')
PY"

